ctor": [ { "id": "http://temp.lincsproject.ca/TzSqx7tztfc/target/BVdwRYPM24h/selector/textQuote/t8en76AKpTV", "type": "TextQuoteSelector", "exact": "Bureau de la traduction du gouvernement fédéral", "prefix": " 

